function buildExceptions(items) {
  return items.filter((row) => row.exception_reason);
}

function computeExceptionReason({ txn, complianceEmailHadSent, hasCompliancePolicyWaiver, statusCorrectionWon }) {
  const reasons = [];

  if (txn.amount_usd > 10000) reasons.push("over_limit");
  if (txn.status === "rejected" && complianceEmailHadSent) reasons.push("compliance_hold");
  if (txn.status === "approved" && txn.amount_usd > 10000 && hasCompliancePolicyWaiver) reasons.push("policy_waiver");
  if (txn.status === "reversed" && txn.amount_usd > 5000 && statusCorrectionWon) reasons.push("retroactive_review");

  if (reasons.length === 0) return null;
  reasons.sort();
  return reasons.join(";");
}

