+// Extract markdown sections by matching whole heading lines.
+// This avoids false matches where the handbook mentions section titles in prose.
+function extractSection(markdown, headingLine) {
+  const escaped = headingLine.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
+  const startRe = new RegExp(`^${escaped}\\s*$`, "m");
+  const startMatch = markdown.match(startRe);
