+const { sortByTransactionId } = require("../utils/sort");
+const { computeExceptionReason } = require("./exceptions");
+
+const STATUS_ORDER = { pending: 0, approved: 1, rejected: 2, reversed: 3 };
+
+function statusUpgrades(fromStatus, toStatus) {
+  const a = STATUS_ORDER[(fromStatus || "").toLowerCase()];
+  const b = STATUS_ORDER[(toStatus || "").toLowerCase()];
+  if (a == null || b == null) return false;
+  return b > a;
+}
+
+function reconcileTransactions(parsed) {
+  // 1) Canonical ledger: only exact section already extracted; skip provisional;
+  // duplicates: keep last non-provisional in file order.
+  const baseById = new Map();
+  for (const row of parsed.ledger) {
+    if (row.provisional) continue;
+    baseById.set(row.transaction_id, {
+      transaction_id: row.transaction_id,
+      owner: row.owner,
+      status: (row.status || "pending").toLowerCase(),
+      ledger_date: row.date,
+      effective_date: row.date,
+      amount_usd: Number(row.amount_usd),
+    });
+  }
+
+  // 2) Amendments (signed only). If amendment has effective, require effective >= ledger_date
+  for (const amend of parsed.meetings) {
+    if (!amend.signed) continue;
+    const txn = baseById.get(amend.transaction_id);
+    if (!txn) continue;
+    if (amend.effective && amend.effective < txn.ledger_date) continue;
+    if (amend.owner) txn.owner = amend.owner;
+  }
+
+  // 3) Email excerpts: compliance@ only; apply only if status moves up precedence.
+  // sent constraint: if sent exists, sent must be >= ledger_date.
+  const complianceEmailHadSentByTxn = new Map();
+  for (const email of parsed.emails) {
+    const txn = baseById.get(email.transaction_id);
+    if (!txn) continue;
+    if (!/compliance@/i.test(email.from_addr || "")) continue;
+
+    if (email.sent) {
+      complianceEmailHadSentByTxn.set(email.transaction_id, true);
+      if (email.sent < txn.ledger_date) continue;
+    }
+
+    const newStatus = (email.status || "").toLowerCase();
+    if (statusUpgrades(txn.status, newStatus)) {
+      txn.status = newStatus;
+    }
+  }
+
+  // 4) Corrections: pick winning notice per txn+field with greatest effective (lexicographic YYYY-MM-DD)
+  const winningByKey = new Map();
+  for (const notice of parsed.corrections) {
+    if (!notice.notice_id || !notice.transaction_id || !notice.field || !notice.effective) continue;
+    const key = `${notice.transaction_id}::${notice.field}`;
+    const prev = winningByKey.get(key);
+    if (!prev || String(notice.effective) > String(prev.effective)) {
+      winningByKey.set(key, notice);
+    }
+  }
+
+  // Build report rows: one per winning correction notice, previous_value before applying.
+  // Sort by notice_id for output; apply corrections after capturing previous_value.
+  const winningNotices = Array.from(winningByKey.values()).sort((a, b) => String(a.notice_id).localeCompare(String(b.notice_id)));
+  const report = [];
+  const statusCorrectionWonByTxn = new Map();
+
+  for (const notice of winningNotices) {
+    const txn = baseById.get(notice.transaction_id);
+    if (!txn) continue;
+
+    const field = notice.field.trim();
+    const newValueRaw = notice.value;
+
+    let previousValue;
+    if (field === "status") previousValue = txn.status;
+    else if (field === "owner") previousValue = txn.owner;
+    else if (field === "date") previousValue = txn.ledger_date;
+    else if (field === "amount") previousValue = txn.amount_usd;
+    else previousValue = txn[field];
+
+    // apply
+    if (field === "status") {
+      txn.status = String(newValueRaw).toLowerCase();
+      txn.effective_date = notice.effective;
+      statusCorrectionWonByTxn.set(txn.transaction_id, true);
+    } else if (field === "date") {
+      txn.ledger_date = String(newValueRaw);
+      txn.effective_date = notice.effective;
+    } else if (field === "owner") {
+      txn.owner = String(newValueRaw);
+    } else if (field === "amount") {
+      txn.amount_usd = Number(newValueRaw);
+    } else {
+      txn[field] = newValueRaw;
+    }
+
+    report.push({
+      notice_id: notice.notice_id,
+      transaction_id: txn.transaction_id,
+      field,
+      previous_value: previousValue,
+      new_value: field === "status" ? String(newValueRaw).toLowerCase() : newValueRaw,
+      effective: notice.effective,
+    });
+  }
+
+  // Finalize items and exceptions
+  const items = Array.from(baseById.values()).map((txn) => {
+    const hasCompliancePolicyWaiver = (() => {
+      const p = parsed.policyExceptions && parsed.policyExceptions.get ? parsed.policyExceptions.get(txn.transaction_id) : null;
+      return p && p.approved_by === "compliance";
+    })();
+    const exception_reason = computeExceptionReason({
+      txn,
+      complianceEmailHadSent: Boolean(complianceEmailHadSentByTxn.get(txn.transaction_id)),
+      hasCompliancePolicyWaiver,
+      statusCorrectionWon: Boolean(statusCorrectionWonByTxn.get(txn.transaction_id)),
+    });
+
+    return {
+      transaction_id: txn.transaction_id,
+      owner: txn.owner,
+      status: txn.status,
+      effective_date: txn.effective_date,
+      amount_usd: Number(txn.amount_usd.toFixed(2)),
+      exception_reason,
+    };
+  });
+
+  items.sort(sortByTransactionId);
+  report.sort((a, b) => String(a.notice_id).localeCompare(String(b.notice_id)));
+  return { items, report };
+}
+
+module.exports = { reconcileTransactions };
+
